from pathlib import Path
import re
p=Path('src/void-apex-answer-combat-v1.js')
s=p.read_text()

def sub(pattern,repl,label):
    global s
    s2,n=re.subn(pattern,repl,s,count=1,flags=re.S)
    if n!=1: raise SystemExit(f'{label}: expected 1 replacement, got {n}')
    s=s2

sub(r"function spikePolygon\(s,reach=1\)\{.*?\}\n  const SPLIT_BAND_HALF=12;", '''function spikePolygon(s,reach=1){
    const r=clamp01(reach),ex=s.origin.x+(s.target.x-s.origin.x)*r,ey=s.origin.y+(s.target.y-s.origin.y)*r,dx=ex-s.origin.x,dy=ey-s.origin.y,d=Math.hypot(dx,dy)||1,ux=dx/d,uy=dy/d,nx=-uy,ny=ux,base=14+r*15,wobble=((s.index||0)%2?1:-1);
    const point=(along,side,skew=0)=>({x:s.origin.x+ux*d*along+nx*base*side+ux*skew,y:s.origin.y+uy*d*along+ny*base*side+uy*skew});
    return[point(0,.58),point(.25,.76),point(.59,.43,wobble*2.4),point(.82,.25,-wobble*1.2),{x:ex,y:ey},point(.80,-.22,wobble*1.4),point(.56,-.38,-wobble*2.2),point(.23,-.67),point(0,-.52)];
  }
  const SPLIT_BAND_HALF=12;''','spike polygon')

sub(r"function rowLaneGeometry\(m,index,reach=1\)\{.*?\n  \}\n  function updateMajor\(dt\)\{", '''function rowLaneGeometry(m,index,reach=1){
    const top=Math.max(frame().visibleDepth+26,vh*.405),bottom=vh*.925,laneH=(bottom-top)/m.count,y0=top+index*laneH+3,y1=top+(index+1)*laneH-3,mid=(y0+y1)*.5,left=vw*.025,right=vw*.975,dir=m.directions?.[index]||1,span=right-left,r=clamp01(reach),tip=dir>0?left+span*r:right-span*r,rear=dir>0?left-54:right+54,len=Math.abs(tip-rear),x=t=>rear+dir*len*t,h=y1-y0;
    const poly=[
      {x:rear,y:mid-h*.36},{x:x(.14),y:y0+h*.12},{x:x(.38),y:y0+h*.04},{x:x(.63),y:y0+h*.16},{x:x(.82),y:y0+h*.08},{x:x(.92),y:mid-h*.20},{x:tip,y:mid},
      {x:x(.90),y:mid+h*.18},{x:x(.74),y:y1-h*.10},{x:x(.48),y:y1-h*.03},{x:x(.22),y:y1-h*.17},{x:rear,y:mid+h*.38}
    ];
    return{top,bottom,laneH,y0,y1,mid,left,right,dir,poly};
  }
  function updateMajor(dt){''','row geometry')

sub(r"function drawSpikes\(\)\{.*?\n  function drawSplit\(m\)\{", '''function drawSpikes(){const t=performance.now()*.001;for(const s of runtime.spikes){const a=s.age;if(a<s.warn){const p=clamp01(a/s.warn),ghost=spikePolygon(s,1);ctx.save();ctx.fillStyle=`rgba(0,0,0,${.025+p*.055})`;ctx.strokeStyle=`rgba(211,215,228,${.30+p*.48})`;ctx.shadowColor=`rgba(226,230,240,${.08+p*.16})`;ctx.shadowBlur=4+p*3;ctx.lineWidth=1.25;ctx.setLineDash([7,8]);ctx.beginPath();ctx.moveTo(ghost[0].x,ghost[0].y);for(let i=1;i<ghost.length;i++)ctx.lineTo(ghost[i].x,ghost[i].y);ctx.closePath();ctx.fill();ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='rgba(0,0,0,.68)';ctx.strokeStyle=`rgba(145,126,174,${.28+p*.28})`;ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(s.origin.x,s.origin.y,8+p*3,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.strokeStyle=`rgba(247,249,255,${.44+p*.50})`;ctx.lineWidth=1.45;ctx.beginPath();ctx.arc(s.target.x,s.target.y,12+(1-p)*7+Math.sin(t*8+s.index)*1.3,0,Math.PI*2);ctx.stroke();ctx.fillStyle=`rgba(250,251,255,${.28+p*.48})`;ctx.beginPath();ctx.arc(s.target.x,s.target.y,2.3+p*1.8,0,Math.PI*2);ctx.fill();ctx.restore();continue;}const elapsed=a-s.warn,total=s.thrust+s.hold+s.retract;if(elapsed>total)continue;let reach=elapsed<s.thrust?elapsed/s.thrust:elapsed<s.thrust+s.hold?1:1-(elapsed-s.thrust-s.hold)/s.retract;reach=clamp01(reach);const poly=spikePolygon(s,reach),ex=s.origin.x+(s.target.x-s.origin.x)*reach,ey=s.origin.y+(s.target.y-s.origin.y)*reach;ctx.save();ctx.shadowColor='rgba(0,0,0,.92)';ctx.shadowBlur=10;ctx.fillStyle='#000000';ctx.strokeStyle='rgba(132,108,158,.50)';ctx.lineWidth=1.35;ctx.beginPath();ctx.moveTo(poly[0].x,poly[0].y);for(let i=1;i<poly.length;i++)ctx.lineTo(poly[i].x,poly[i].y);ctx.closePath();ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.strokeStyle='rgba(68,49,88,.55)';ctx.lineWidth=2.2;ctx.beginPath();ctx.moveTo(s.origin.x,s.origin.y);ctx.lineTo(s.origin.x+(ex-s.origin.x)*.68,s.origin.y+(ey-s.origin.y)*.68);ctx.stroke();ctx.fillStyle='#000';ctx.strokeStyle='rgba(108,86,132,.44)';ctx.lineWidth=1.1;ctx.beginPath();ctx.arc(s.origin.x,s.origin.y,11+reach*3,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore();}}
  function drawSplit(m){''','draw spikes')

sub(r"function drawSplit\(m\)\{.*?\n  function drawBeam\(m\)\{", '''function drawSplit(m){const line=m.line,ux=Math.cos(line.a),uy=Math.sin(line.a),x1=line.cx-ux*line.span,y1=line.cy-uy*line.span,x2=line.cx+ux*line.span,y2=line.cy+uy*line.span,nx=-uy,ny=ux,band=SPLIT_BAND_HALF;if(m.age<m.warn){const p=clamp01(m.age/m.warn);ctx.save();ctx.strokeStyle=`rgba(0,0,0,${.045+p*.075})`;ctx.lineWidth=band*2;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();ctx.strokeStyle=`rgba(232,236,246,${.18+p*.58})`;ctx.lineWidth=1.2+p*1.45;ctx.setLineDash([9,11]);ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle=`rgba(177,184,203,${.10+p*.22})`;ctx.lineWidth=1;for(const side of[-1,1]){ctx.beginPath();ctx.moveTo(x1+nx*band*side,y1+ny*band*side);ctx.lineTo(x2+nx*band*side,y2+ny*band*side);ctx.stroke();}ctx.restore();return;}const elapsed=m.age-m.warn,alpha=elapsed<=m.active?1:1-clamp01((elapsed-m.active)/m.fade);ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle='rgba(0,0,0,.52)';ctx.lineWidth=(band+4)*2;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();ctx.strokeStyle='#000000';ctx.lineWidth=band*2;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();ctx.strokeStyle='rgba(190,197,216,.26)';ctx.lineWidth=1.1;for(const side of[-1,1]){ctx.beginPath();ctx.moveTo(x1+nx*band*side,y1+ny*band*side);ctx.lineTo(x2+nx*band*side,y2+ny*band*side);ctx.stroke();}const flow=(performance.now()*.075)%54;ctx.lineWidth=1.6;ctx.setLineDash([7,20]);for(const [i,off] of[-6,0,6].entries()){ctx.strokeStyle=`rgba(${70+i*8},${56+i*6},${92+i*10},${.22+i*.055})`;ctx.lineDashOffset=-flow-i*13;ctx.beginPath();ctx.moveTo(x1+nx*off,y1+ny*off);ctx.lineTo(x2+nx*off,y2+ny*off);ctx.stroke();}ctx.restore();}
  function drawBeam(m){''','draw split')

sub(r"function drawBeam\(m\)\{.*?\n  function drawRow\(m\)\{", '''function drawBeam(m){const f=frame(),x=vw*.5,start=Math.max(20,f.visibleDepth*.18);if(m.age<m.warn){const p=clamp01(m.age/m.warn),pulse=.5+.5*Math.sin(performance.now()*.012);ctx.save();ctx.globalCompositeOperation='screen';ctx.fillStyle=`rgba(238,246,255,${.012+p*.045})`;ctx.fillRect(x-m.width*.5,start,m.width,vh-start);ctx.strokeStyle=`rgba(238,244,255,${.16+p*.42})`;ctx.lineWidth=1;for(const side of[-1,1]){ctx.beginPath();ctx.moveTo(x+side*m.width*.5,start);ctx.lineTo(x+side*m.width*.5,vh);ctx.stroke();}ctx.strokeStyle=`rgba(255,255,255,${.28+p*.68})`;ctx.shadowColor='#ffffff';ctx.shadowBlur=5+p*13;ctx.lineWidth=1.2+p*2.2;ctx.beginPath();ctx.moveTo(x,start);ctx.lineTo(x,vh);ctx.stroke();const r=26+p*24+pulse*4,g=ctx.createRadialGradient(x,start,0,x,start,r);g.addColorStop(0,`rgba(255,255,255,${.24+p*.46})`);g.addColorStop(.38,`rgba(239,247,255,${.08+p*.20})`);g.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=g;ctx.fillRect(x-r,start-r,r*2,r*2);ctx.restore();return;}const e=m.age-m.warn,alpha=e<=m.active?1:1-clamp01((e-m.active)/m.fade);ctx.save();ctx.globalCompositeOperation='screen';ctx.globalAlpha=alpha;ctx.shadowColor='#ffffff';ctx.shadowBlur=30;ctx.fillStyle='rgba(244,249,255,.24)';ctx.fillRect(x-m.width*.5-12,start,m.width+24,vh-start);ctx.fillStyle='#ffffff';ctx.fillRect(x-m.width*.5,start,m.width,vh-start);ctx.shadowBlur=12;ctx.fillStyle='rgba(255,255,255,.98)';ctx.fillRect(x-m.width*.18,start,m.width*.36,vh-start);ctx.restore();}
  function drawRow(m){''','draw beam')

sub(r"function drawRow\(m\)\{.*?\n  function drawClone\(c\)\{", '''function drawRow(m){for(let i=0;i<m.count;i++){const fake=m.fake.has(i),crumbled=m.crumble.has(i);if(crumbled)continue;if(m.age<m.warn){const p=clamp01(m.age/m.warn),g=rowLaneGeometry(m,i,1),originX=g.dir>0?g.left+12:g.right-12;ctx.save();ctx.fillStyle=fake?`rgba(255,255,255,${.008+p*.018})`:`rgba(0,0,0,${.025+p*.055})`;ctx.strokeStyle=fake?`rgba(255,255,255,${.48+p*.45})`:`rgba(123,102,151,${.30+p*.40})`;ctx.shadowColor=fake?'rgba(255,255,255,.38)':'rgba(72,51,92,.30)';ctx.shadowBlur=fake?8:4;ctx.lineWidth=fake?1.7:1.3;ctx.setLineDash(fake?[10,8]:[5,11]);ctx.beginPath();ctx.moveTo(g.poly[0].x,g.poly[0].y);for(let j=1;j<g.poly.length;j++)ctx.lineTo(g.poly[j].x,g.poly[j].y);ctx.closePath();ctx.fill();ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle=fake?`rgba(255,255,255,${.24+p*.40})`:`rgba(91,70,116,${.18+p*.24})`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(g.dir>0?g.left:g.right,g.mid);ctx.lineTo(g.dir>0?g.right:g.left,g.mid);ctx.stroke();ctx.fillStyle=fake?'rgba(255,255,255,.82)':'rgba(4,3,7,.92)';ctx.strokeStyle=fake?'rgba(255,255,255,.95)':'rgba(133,108,159,.62)';ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(originX,g.mid,4.2+p*1.8,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore();continue;}const elapsed=m.age-m.warn,reach=elapsed<m.active?clamp01(elapsed/.18):1,alpha=elapsed<=m.active?1:1-clamp01((elapsed-m.active)/m.fade),g=rowLaneGeometry(m,i,reach);ctx.save();ctx.globalAlpha=alpha;if(fake)ctx.globalCompositeOperation='screen';ctx.shadowColor=fake?'rgba(255,255,255,.70)':'rgba(0,0,0,.95)';ctx.shadowBlur=fake?14:9;ctx.fillStyle=fake?'rgba(248,251,255,.88)':'#000000';ctx.strokeStyle=fake?'rgba(255,255,255,.98)':'rgba(126,96,153,.58)';ctx.lineWidth=fake?1.9:1.35;ctx.beginPath();ctx.moveTo(g.poly[0].x,g.poly[0].y);for(let j=1;j<g.poly.length;j++)ctx.lineTo(g.poly[j].x,g.poly[j].y);ctx.closePath();ctx.fill();ctx.stroke();ctx.shadowBlur=0;if(fake){ctx.strokeStyle='rgba(205,216,232,.58)';ctx.lineWidth=1.15;ctx.setLineDash([13,15]);ctx.beginPath();ctx.moveTo(g.dir>0?g.left:g.right,g.mid);ctx.lineTo(g.dir>0?g.right:g.left,g.mid);ctx.stroke();ctx.setLineDash([]);}else{ctx.strokeStyle='rgba(57,40,75,.62)';ctx.lineWidth=2;for(const off of[-.18,0,.17]){ctx.beginPath();ctx.moveTo(g.dir>0?g.left-14:g.right+14,g.mid+(g.y1-g.y0)*off);ctx.lineTo(g.dir>0?g.poly[6].x-28:g.poly[6].x+28,g.mid+(g.y1-g.y0)*off*.55);ctx.stroke();}}ctx.restore();}}
  function drawClone(c){''','draw row')

old="spikes:runtime.spikes.length,major:runtime.major?.kind||null,majorCd:{...runtime.majorCd}"
new="spikes:runtime.spikes.length,spikeDetails:runtime.spikes.map(s=>({age:s.age,warn:s.warn,thrust:s.thrust,hold:s.hold,retract:s.retract})),major:runtime.major?.kind||null,majorDetails:runtime.major?{kind:runtime.major.kind,age:runtime.major.age,warn:runtime.major.warn,active:runtime.major.active,fade:runtime.major.fade}:null,majorCd:{...runtime.majorCd}"
if old not in s: raise SystemExit('diagnostics anchor missing')
s=s.replace(old,new,1)
p.write_text(s)
print('patched Answer hazard presentation')
